-- Checkpoint 09 PostgreSQL catalog schema starter (PostgreSQL 15+).
-- Apply on a new database; do NOT apply blindly to production databases.
BEGIN;
CREATE TABLE IF NOT EXISTS categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS networks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT);
CREATE TABLE IF NOT EXISTS sites (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,network_id BIGINT REFERENCES networks(id),name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,last_updated TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS channels (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,site_id BIGINT REFERENCES sites(id),name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS performers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,country TEXT);
CREATE TABLE IF NOT EXISTS videos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,site_id BIGINT REFERENCES sites(id),channel_id BIGINT REFERENCES channels(id),poster TEXT,media_url TEXT,duration INT CHECK(duration>=0),quality TEXT,views BIGINT NOT NULL DEFAULT 0,likes BIGINT NOT NULL DEFAULT 0,dislikes BIGINT NOT NULL DEFAULT 0,published_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'PUBLISHED');
CREATE TABLE IF NOT EXISTS video_categories (video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,category_id BIGINT NOT NULL REFERENCES categories(id),PRIMARY KEY(video_id,category_id));
CREATE TABLE IF NOT EXISTS video_performers (video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,performer_id BIGINT NOT NULL REFERENCES performers(id),PRIMARY KEY(video_id,performer_id));
CREATE TABLE IF NOT EXISTS video_chapters (video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,start_seconds DOUBLE PRECISION NOT NULL CHECK(start_seconds>=0),title TEXT NOT NULL,PRIMARY KEY(video_id,start_seconds));
CREATE TABLE IF NOT EXISTS video_captions (video_id BIGINT PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE,vtt TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en');
CREATE INDEX IF NOT EXISTS ix_videos_published ON videos(published_at DESC) WHERE status='PUBLISHED';
CREATE INDEX IF NOT EXISTS ix_videos_views ON videos(views DESC) WHERE status='PUBLISHED';
CREATE INDEX IF NOT EXISTS ix_videos_site ON videos(site_id);
CREATE INDEX IF NOT EXISTS ix_videos_channel ON videos(channel_id);
CREATE INDEX IF NOT EXISTS ix_video_categories_category ON video_categories(category_id,video_id);
CREATE INDEX IF NOT EXISTS ix_video_performers_performer ON video_performers(performer_id,video_id);
COMMIT;
